//! Hyperdual number comparisons against the exact-source library.
//! Generated by tools/rust_port/validate_hyperdual.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::hyperdual::HyperDual;

const FUNCTIONS: usize = 12;

fn build(inputs: &[f64]) -> HyperDual {
    let mut number = HyperDual::with_order(inputs[0], inputs[8] as u8);
    number.f1 = inputs[1];
    number.f2 = inputs[2];
    number.f3 = inputs[3];
    number.f12 = inputs[4];
    number.f13 = inputs[5];
    number.f23 = inputs[6];
    number.f123 = inputs[7];
    number
}

fn evaluate(number: &HyperDual) -> Vec<HyperDual> {
    vec![
        number.exp(),
        number.ln(),
        number.sqrt(),
        number.sin(),
        number.cos(),
        number.tan(),
        number.sinh(),
        number.cosh(),
        number.tanh(),
        number.asin(),
        number.acos(),
        number.atan(),
    ]
}

#[test]
fn hyperdual_matches_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/hyperdual.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let inputs: Vec<f64> = fields[0].split(',').map(|v| v.parse().unwrap()).collect();
        let expected: Vec<f64> = fields[1].split(',').map(|v| v.parse().unwrap()).collect();
        assert_eq!(expected.len(), FUNCTIONS * 8);
        let number = build(&inputs);
        let actual: Vec<f64> = evaluate(&number)
            .iter()
            .flat_map(|value| {
                [
                    value.f0, value.f1, value.f2, value.f3, value.f12, value.f13, value.f23,
                    value.f123,
                ]
            })
            .collect();
        for (position, (source, native)) in expected.iter().zip(&actual).enumerate() {
            if source.is_nan() && native.is_nan() {
                // Both sides reproduce the same undefined value.
                continue;
            }
            assert!(
                (source - native).abs() <= 1e-14 + 1e-12 * source.abs(),
                "quantity {position}: source {source} native {native}"
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 6);
}

#[test]
fn the_atan_double_power_is_preserved() {
    // The original writes `deriv**3**v1%f1` in the third order derivative of
    // the arc tangent, so the exponent of the derivative is three raised to
    // the first derivative of the argument.
    let mut number = HyperDual::with_order(0.75, 3);
    number.f1 = 0.5;
    number.f2 = -1.5;
    number.f3 = 2.0;
    number.f12 = 1.0;
    number.f13 = -0.5;
    number.f23 = 0.25;
    number.f123 = 0.125;
    let value = number.atan();
    let derivative: f64 = 1.0 / (1.0 + 0.75 * 0.75);
    let second = -2.0 * 0.75 * derivative * derivative;
    let expected = derivative * 0.125
        + second * (1.0 * 2.0 + (-0.5) * (-1.5) + 0.25 * 0.5)
        + (6.0 * 0.75 * 0.75 - 2.0) * derivative.powf(3.0f64.powf(0.5)) * (-1.5) * 2.0;
    assert!((value.f123 - expected).abs() < 1e-12);
}
